function bindPasswordToggle(buttonId,inputId){const button=$('#'+buttonId),input=$('#'+inputId);button.onclick=()=>{const visible=input.type==='password';input.type=visible?'text':'password';button.textContent=visible?'Hide':'Show';button.setAttribute('aria-label',visible?'Hide password':'Show password');button.setAttribute('aria-pressed',String(visible))}}document.body.addEventListener('click',e=>{if(e.target.id==='generateCoupon')document.getElementById('couponCodeNew').value='GATHA-'+Math.random().toString(36).slice(2,7).toUpperCase()});document.body.addEventListener('submit',e=>{if(e.target.id!=='couponForm')return;e.preventDefault();const f=new FormData(e.target),code=String(f.get('code')||'').trim().toUpperCase(),type=f.get('type'),value=Number(f.get('value')),minimumOrder=Number(f.get('minimumOrder')||0),startsOn=String(f.get('startsOn')||''),endsOn=String(f.get('endsOn')||'');if(!/^[A-Z0-9_-]{3,24}$/.test(code)||!Number.isFinite(value)||value<=0||(type==='percent'&&value>100)||db.coupons.some(c=>c.code===code)){toast('Enter a unique valid code and discount.');return}if(startsOn&&endsOn&&startsOn>endsOn){toast('End date must be after start date.');return}db.coupons=db.coupons||[];db.coupons.unshift({id:uid(),code,type,value,minimumOrder,startsOn,endsOn,membershipOnly:f.has('membershipOnly'),active:true,usedCount:0});save();renderSettings();toast('Coupon created.')});document.body.addEventListener('click',e=>{const toggle=e.target.closest('[data-toggle-coupon]'),remove=e.target.closest('[data-delete-coupon]');if(!toggle&&!remove)return;const id=toggle?toggle.dataset.toggleCoupon:remove.dataset.deleteCoupon,c=(db.coupons||[]).find(x=>x.id===id);if(!c)return;if(remove){if(!confirm('Delete this coupon?'))return;db.coupons=db.coupons.filter(x=>x.id!==id)}else c.active=c.active===false;save();renderSettings()});document.body.addEventListener('input',e=>{if(e.target.id==='couponCode')calcBill()});bindPasswordToggle('togglePassword','password');bindPasswordToggle('toggleRecoveryPassword','recoveryPassword');refreshOwnerSetup();
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();let u=$('#username').value.trim(),p=$('#password').value,code=ownerSetupMode?makeRecoveryCode():'';$('#loginError').textContent='';try{const call=async(endpoint,body)=>{let r=await window.gathaFetch(window.gathaApiUrl(endpoint),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw Error(d.error||'Sign in failed');return d};let account;if(ownerSetupMode){await call('setup',{username:u,password:p,phone:$('#setupPhone').value,recoveryCode:code});alert(`Owner account created. Save this backup recovery code somewhere secure and separate from your password:\n\n${code}\n\nIt will not be shown again.`);ownerSetupMode=false;account=await call('login',{username:u,password:p})}else account=await call('login',{username:u,password:p});setUser(account.role)}catch(err){$('#loginError').textContent=err.message==='fetch failed'?'The shop server is unavailable.':err.message}});
