document.body.addEventListener('click',e=>{if(e.target.id!=='setupRecovery')return;openModal(`<div class="modal-top"><h2>Set up account recovery</h2><button class="modal-close" data-close>×</button></div><form id="recoverySetupForm"><div class="field"><label for="ownerRecoveryPhone">Your phone number</label><input id="ownerRecoveryPhone" type="tel" inputmode="tel" required placeholder="10-digit mobile number"></div><p class="help">A new private backup code will be generated. Keep it somewhere secure; it is required together with this phone number to reset your password.</p><div class="form-actions"><button type="button" class="btn outline" data-close>Cancel</button><button class="btn primary">Save recovery details</button></div></form>`);$('#recoverySetupForm').onsubmit=async ev=>{ev.preventDefault();const code=makeRecoveryCode();try{const r=await window.gathaFetch(window.gathaApiUrl('recovery-setup'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone:$('#ownerRecoveryPhone').value,recoveryCode:code})}),d=await r.json();if(!r.ok)throw Error(d.error||'Could not save recovery details.');closeModal();alert(`Recovery set up. Save this backup code somewhere secure and separate from your password:\n\n${code}\n\nIt will not be shown again.`)}catch(err){toast(err.message)}}});$('#logout').onclick=async()=>{try{await window.gathaFetch(window.gathaApiUrl('logout'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'})}catch{}setUser(null)};$('#mobileLogout').onclick=()=>$('#logout').click();$('#sidebarToggle').onclick=()=>{const collapsed=$('#app').classList.toggle('sidebar-collapsed');$('#sidebarToggle').setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar')};
$('#nav').addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b){$('#mobileMore').open=false;go(b.dataset.page)}});document.body.addEventListener('click',e=>{let goBtn=e.target.closest('[data-go]');if(goBtn){go(goBtn.dataset.go);return}let close=e.target.closest('[data-close]');if(close){closeModal();return}let p=e.target.closest('[data-period]');if(p){period=p.dataset.period;render();return}let edit=e.target.closest('[data-edit-member]');if(edit){let m=db.members.find(x=>x.id===edit.dataset.editMember||x.number===edit.dataset.editMember);if(m)editMemberModal(m);return}let card=e.target.closest('[data-card]');if(card){let m=db.members.find(x=>x.id===card.dataset.card||x.number===card.dataset.card);if(m)membershipCard(m);return}let renew=e.target.closest('[data-renew]');if(renew){let m=db.members.find(x=>x.id===renew.dataset.renew);if(m)membershipModal(m);return}let rem=e.target.closest('[data-remind]');if(rem){let m=db.members.find(x=>x.id===rem.dataset.remind);if(m)remind(m);return}let stockWa=e.target.closest('[data-stock-wa]');if(stockWa){let campaign=(db.campaigns||[]).find(x=>x.id===stockWa.dataset.stockWa),m=db.members.find(x=>x.id===stockWa.dataset.member);if(campaign&&m){let msg=`Hi ${m.name}, ${db.shop} has new arrivals: ${campaign.title}. ${campaign.description} Show your membership ${m.number} to enjoy member benefits. Reply STOP if you no longer want updates.`;let phone=phoneKey(m.phone),tab=window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank');if(tab){tab.opener=null;toast('Message opened in WhatsApp. Review it and tap Send.')}else toast('Allow pop-ups to open WhatsApp.')}return}let sent=e.target.closest('[data-stock-sent]');if(sent){let c=(db.campaigns||[]).find(x=>x.id===sent.dataset.stockSent),id=sent.dataset.member;if(c){c.sentIds=c.sentIds||[];if(!c.sentIds.includes(id))c.sentIds.push(id);save();renderStock();toast('Marked as sent.')}return}let wa=e.target.closest('[data-whatsapp]');if(wa){let m=db.members.find(x=>x.id===wa.dataset.whatsapp||x.number===wa.dataset.whatsapp);if(m)sendWelcomeWhatsApp(m);return}let method=e.target.closest('[data-method]');if(method){payMethod=method.dataset.method;$$('.sale-methods [data-method]').forEach(x=>x.classList.toggle('chosen',x.dataset.method===payMethod));return}if(e.target.id==='newMember'){membershipModal();return}if(e.target.id==='lookupBtn'){lookup();return}if(e.target.id==='buyMembership'){let q=$('#lookup').value.trim();let prior=db.members.find(m=>phoneKey(m.phone)===phoneKey(q));if(prior){toast('This customer already has a membership.');return}openModal(`<div class="modal-top"><h2>Add a member</h2><button class="modal-close" data-close>×</button></div><p class="help">No member record found. Enter their name and phone to activate a ₹99 membership.</p><form id="buyForm"><div class="form-grid"><div class="field full-row"><label>Full name</label><input name="name" required></div><div class="field full-row"><label>Phone number</label><input name="phone" required value="${esc(q)}"></div><div class="field"><label>Email (optional)</label><input name="email" type="email"></div><div class="field"><label>Fee payment method</label><select name="method"><option>UPI</option><option>Cash</option><option>Card</option></select></div></div><div class="settings-note" style="margin-top:13px">₹99 · Valid for 365 days · Discount applies to this checkout.</div><div class="form-actions"><button type="button" class="btn outline" data-close>Cancel</button><button class="btn primary">Record ₹99 &amp; activate</button></div></form>`);$('#buyForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.currentTarget),phone=String(f.get('phone')).trim();if(db.members.some(x=>phoneKey(x.phone)===phoneKey(phone))){toast('This phone number already has a membership.');return}let date=dateISO(),m={id:uid(),name:String(f.get('name')).trim(),phone,email:String(f.get('email')).trim(),number:nextMembershipNumber(date),joined:date,expiry:addYear(date),status:'ACTIVE'};db.members.push(m);db.fees.push({id:uid(),memberId:m.id,number:m.number,amount:99,date:new Date().toISOString(),method:f.get('method'),type:'new'});save();closeModal();sendWelcomeWhatsApp(m);checkoutMember=m;$('#lookup').value=m.phone;$('#lookupResult').innerHTML=`<div class="member-result"><span>${nameCell(m)}</span><span class="badge">Active</span></div>`;$('#checkoutStatus').innerHTML=`<b>${Number(db.membershipDiscountPercent??15)}% discount applied</b> · Valid until ${fmt(m.expiry)}.`;calcBill();toast('Membership added and discount applied.')};return}let add=e.target.closest('#addItem');if(add){addItem();return}let del=e.target.closest('.remove');if(del){if($$('.item-row').length>1)del.closest('.item-row').remove();calcBill();return}if(e.target.closest('#completeSale')){completeSale();return}let rc=e.target.closest('[data-receipt]');if(rc){let s=db.sales.find(x=>x.id===rc.dataset.receipt);if(s)showReceipt(s);return}if(e.target.id==='exportMembers'){exportMembers();return}if(e.target.id==='exportSales'){exportSales();return}if(e.target.id==='backupData'){download('memberly-backup.json',JSON.stringify(db,null,2));return}if(e.target.id==='resetData'){if(confirm('Permanently remove all members, sales, fees and shop settings from this browser?')){db={...defaults};save();render();toast('Local data has been reset.')}return}});
